alter policy "assignment targeted read" on public.schoolpro_assignments using(
 private.schoolpro_module_allowed(school_id,'assignments') and (
 private.has_school_access(school_id,array['proprietor','administrator','head_teacher','vice_principal']::public.school_member_role[])
 or exists(select 1 from public.schoolpro_subject_assignments a join public.schoolpro_members m on m.id=a.teacher_member_id and m.school_id=a.school_id where a.school_id=schoolpro_assignments.school_id and a.class_id=schoolpro_assignments.class_id and a.subject_id=schoolpro_assignments.subject_id and a.session=schoolpro_assignments.session and m.user_id=auth.uid())
 or exists(select 1 from public.schoolpro_classes c join public.schoolpro_members m on m.id=c.form_teacher_id and m.school_id=c.school_id where c.id=schoolpro_assignments.class_id and c.school_id=schoolpro_assignments.school_id and m.user_id=auth.uid())
 or exists(select 1 from public.schoolpro_students s left join public.schoolpro_enrollment_history e on e.school_id=s.school_id and e.student_id=s.id and e.session=schoolpro_assignments.session where s.school_id=schoolpro_assignments.school_id and coalesce(e.class_id,s.class_id)=schoolpro_assignments.class_id and (s.user_id=auth.uid() or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=auth.uid() and g.status='active')))
 ));
create policy "family historical timetable read" on public.schoolpro_timetable_entries for select to authenticated using(
 private.schoolpro_module_allowed(school_id,'timetable') and exists(select 1 from public.schoolpro_students s left join public.schoolpro_enrollment_history e on e.school_id=s.school_id and e.student_id=s.id and e.session=schoolpro_timetable_entries.session where s.school_id=schoolpro_timetable_entries.school_id and coalesce(e.class_id,s.class_id)=schoolpro_timetable_entries.class_id and (s.user_id=auth.uid() or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=auth.uid() and g.status='active')))
);